import React, { useState, useMemo } from 'react';
import BaseNode from './BaseNode';

export const TextNode = ({ data }) => {
  const [text, setText] = useState(data.text || '');

  // Extract variables like {{input}}
  const variables = useMemo(() => {
    const matches = text.match(/{{\s*([a-zA-Z_$][a-zA-Z0-9_$]*)\s*}}/g) || [];
    return [...new Set(matches.map(v => v.slice(2, -2).trim()))];
  }, [text]);

  // Generate handles from variables
  const handles = [
    ...variables.map(v => ({ id: v, type: 'target', position: 'left' })),
    { id: 'output', type: 'source', position: 'right' }
  ];

  return (
    <BaseNode
      data={{
        ...data,
        label: 'TEXT',
        className: 'text-node',
        content: (
          <div>
            <textarea
              value={text}
              onChange={(e) => setText(e.target.value)}
              className="w-full p-1 text-xs border rounded focus:ring-1 focus:ring-blue-500 resize-none"
              placeholder="Enter text... Use {{variable}} for inputs"
              style={{ minHeight: '60px', overflow: 'hidden' }}
            />
            <div className="mt-2 text-xs text-gray-600">
              Variables detected: {variables.length > 0 ? variables.map(v => (
                <span key={v} className="inline-block px-1 py-0.5 mx-0.5 text-xs bg-blue-100 text-blue-800 rounded">
                  {v}
                </span>
              )) : 'None'}
            </div>
          </div>
        ),
        handles
      }}
    />
  );
};
